package com.nigson.integration.provider;

import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
import tools.jackson.databind.JsonNode;import com.nigson.integration.provider.PrivateHttp;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;

/** Google Sheets Values API adapter. Row lookup uses the immutable application ID in column A. */
public final class GoogleSheetsHttpAdapter implements GoogleSheetsPort {
 private static final int ROW_LIMIT=5000;private final URI base;private final GoogleServiceAccountTokenProvider tokens;private final HttpClient http;private final String tab;
 public GoogleSheetsHttpAdapter(String env,String apiBase,String tab,GoogleServiceAccountTokenProvider tokens){URI uri=URI.create(apiBase);if(!Set.of("local","test","dev","qa","stage","prod").contains(env)||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!Set.of("","/").contains(uri.getPath())||tab==null||!tab.matches("[A-Za-z0-9 _-]{1,80}"))throw new IllegalArgumentException("GOOGLE_SHEETS_API_CONFIG_REQUIRED");if(Set.of("local","test").contains(env)){if(!"http".equals(uri.getScheme())||!Set.of("127.0.0.1","localhost").contains(uri.getHost()))throw new IllegalArgumentException("LOCAL_SHEETS_MOCK_REQUIRED");}else if(!"https".equals(uri.getScheme())||!"sheets.googleapis.com".equals(uri.getHost())||uri.getPort()!=-1)throw new IllegalArgumentException("GOOGLE_SHEETS_API_REQUIRED");base=URI.create(uri.getScheme()+"://"+uri.getAuthority());this.tab=tab;this.tokens=Objects.requireNonNull(tokens);http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 public Optional<String> contentHash(String spreadsheetKey,String rowKey){var sheet=validate(spreadsheetKey,rowKey);JsonNode values=read(sheet);var found=find(values,rowKey);return found==null?Optional.empty():Optional.of(found.hash());}
 public boolean safeToCreateAfterConfirmedAbsence(){return false;}
 public void upsert(String spreadsheetKey,String rowKey,CareerSheetRow row,String contentHash,String commandKey){var sheet=validate(spreadsheetKey,rowKey);if(row==null||!row.applicationId().toString().equals(rowKey)||contentHash==null||!contentHash.matches("[a-f0-9]{64}")||commandKey==null||commandKey.isBlank())throw ApiValues.invalid();JsonNode values=read(sheet);var existing=find(values,rowKey);var cells=new ArrayList<String>();cells.add(rowKey);cells.add(contentHash);cells.addAll(row.cells().subList(1,row.cells().size()));var body=EventCodec.JSON.writeValueAsString(Map.of("majorDimension","ROWS","values",List.of(cells)));URI target;if(existing!=null)target=valuesUri(sheet,tab+"!A"+existing.row()+":AZ"+existing.row(),"?valueInputOption=RAW");else{if(values.size()>=ROW_LIMIT)throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);target=valuesUri(sheet,tab+"!A:AZ",":append?valueInputOption=RAW&insertDataOption=INSERT_ROWS&includeValuesInResponse=false");}var builder=HttpRequest.newBuilder(target).timeout(Duration.ofSeconds(7)).header("Authorization","Bearer "+tokens.token()).header("Accept","application/json").header("Content-Type","application/json");var request=existing==null?builder.POST(HttpRequest.BodyPublishers.ofString(body)).build():builder.PUT(HttpRequest.BodyPublishers.ofString(body)).build();var response=PrivateHttp.send(http,request,32768,Duration.ofSeconds(8));if(!Set.of(200,201).contains(response.statusCode())||response.headers().allValues("Content-Type").size()!=1||!response.headers().firstValue("Content-Type").orElse("").split(";",2)[0].strip().equals("application/json"))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}
 private URI validate(String sheet,String row){if(sheet==null||!sheet.matches("[A-Za-z0-9_-]{1,120}")||row==null||!row.matches("[0-9a-fA-F-]{36}"))throw ApiValues.invalid();return base.resolve("v4/spreadsheets/"+sheet);}
 private URI valuesUri(URI sheet,String range,String suffix){String encoded=URLEncoder.encode(range,StandardCharsets.UTF_8).replace("+","%20");return URI.create(sheet+"/values/"+encoded+suffix+(suffix.contains("?")?"":"?valueRenderOption=UNFORMATTED_VALUE"));}
 private JsonNode read(URI sheet){URI uri=valuesUri(sheet,tab+"!A1:B"+ROW_LIMIT,"");var request=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(7)).header("Authorization","Bearer "+tokens.token()).header("Accept","application/json").GET().build();var response=PrivateHttp.send(http,request,65536,Duration.ofSeconds(8));if(response.statusCode()!=200||response.headers().allValues("Content-Type").size()!=1||!response.headers().firstValue("Content-Type").orElse("").split(";",2)[0].strip().equals("application/json"))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var json=EventCodec.JSON.readTree(response.body());if(!json.isObject())throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);JsonNode values=json.get("values");if(values==null)return EventCodec.JSON.createArrayNode();if(!values.isArray()||values.size()>ROW_LIMIT)throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);return values;}
 private record Found(int row,String hash){}
 private Found find(JsonNode values,String key){Found found=null;for(int i=0;i<values.size();i++){var cells=values.get(i);if(!cells.isArray()||cells.isEmpty())continue;var app=cells.get(0);if(app.isString()&&app.asString().equals(key)){if(found!=null)throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);if(cells.size()<2||!cells.get(1).isString()||!cells.get(1).asString().matches("[a-f0-9]{64}"))throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);found=new Found(i+1,cells.get(1).asString());}}return found;}
}
